g=[[1]*30 for _ in range(30)]
rowstarts=[1,9,16]; colstarts=[1,10,20]
colors=[[2,4,3],[3,6,9],[9,4,5]]
for ri,r0 in enumerate(rowstarts):
 for ci,c0 in enumerate(colstarts):
  for r in range(r0,r0+6):
   for c in range(c0,c0+6): g[r][c]=8
  for r in range(r0+2,r0+4):
   for c in range(c0+2,c0+4): g[r][c]=colors[ri][ci]
legend=[2,4,3,9,5,4,6,3,9]
for i,v in enumerate(legend): g[28][1+2*i]=v
# horizontal/vertical connectors between successive positions on the 3x3 tile lattice
positions={2:(0,0),4:(0,1),3:(0,2),9:(1,2),5:(2,2),4:(2,1),6:(1,1),3:(1,0),9:(2,0)}
# duplicates are okay because sequence occurrences identify path positions; use coordinate sequence directly
seqcoords=[(0,0),(0,1),(0,2),(1,2),(2,2),(2,1),(1,1),(1,0),(2,0)]
for (r1,c1),(r2,c2),color in zip(seqcoords,seqcoords[1:],legend):
 rcenter=rowstarts[r1]+2; ccenter=colstarts[c1]+2
 if r1==r2:
  lo=colstarts[min(c1,c2)]+6; hi=colstarts[max(c1,c2)]
  for r in range(rcenter,rcenter+2):
   for c in range(lo,hi):g[r][c]=color
 else:
  lo=rowstarts[min(r1,r2)]+6; hi=rowstarts[max(r1,r2)]
  for r in range(lo,hi):
   for c in range(ccenter,ccenter+2):g[r][c]=color
